void PutVarint32(std::string* dst, uint32_t v) {
    // While the value is greater than 127, write the least significant 7 bits with MSB set to 1
    while (v > 127) {
        dst->push_back(static_cast<char>((v & 0x7F) | 0x80));
        v >>= 7;
    }
    // Write the remaining 7 bits with MSB set to 0
    dst->push_back(static_cast<char>(v));
}

